import{G as e,K as t,at as n,j as r}from"./chunks/framework.DrNIf5Lg.js";var i=JSON.parse(`{"title":"故障排除","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/troubleshooting.md","filePath":"zh/guide/troubleshooting.md"}`),a={name:`zh/guide/troubleshooting.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="故障排除" tabindex="-1">故障排除 <a class="header-anchor" href="#故障排除" aria-label="Permalink to “故障排除”">​</a></h1><p>使用 StaticPHP 过程中可能会碰到各种各样的故障，这里将讲述如何自行查看错误并反馈 Issue。</p><h2 id="下载失败问题" tabindex="-1">下载失败问题 <a class="header-anchor" href="#下载失败问题" aria-label="Permalink to “下载失败问题”">​</a></h2><p>下载资源问题是 spc 最常见的问题之一。主要是由于 spc 下载资源使用的地址一般均为对应项目的官方网站或 GitHub 等，而这些网站可能偶尔会宕机、屏蔽 IP 地址。 在遇到下载失败后，可以多次尝试调用下载命令。</p><p>当下载资源时，你可能最终会看到类似 <code>curl: (56) The requested URL returned error: 403</code> 的错误，这通常是由于 GitHub 限制导致的。 你可以通过在命令中添加 <code>-vvv</code> 来验证，会看到类似 <code>[DEBU] Running command (no output) : curl -sfSL &quot;https://api.github.com/repos/openssl/openssl/releases&quot;</code> 的输出。</p><p>要解决这个问题，可以在 GitHub 上 <a href="https://github.com/settings/tokens" target="_blank" rel="noreferrer">创建</a> 一个个人访问令牌，并将其设置为环境变量 <code>GITHUB_TOKEN=&lt;XXX&gt;</code>。</p><p>如果确认地址确实无法正常访问，可以提交 Issue 或 PR 更新地址或下载类型。</p><h2 id="通过代理下载" tabindex="-1">通过代理下载 <a class="header-anchor" href="#通过代理下载" aria-label="Permalink to “通过代理下载”">​</a></h2><p>如果你的网络需要通过代理才能访问下载源，可以直接设置 <code>ALL_PROXY</code>，也可以使用 <code>SPC_PROXY</code>：</p><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># curl 和 git 本来就会读取 ALL_PROXY</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ALL_PROXY</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;socks5h://127.0.0.1:1080&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> spc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> download</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --for-extensions=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;curl,openssl&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># SPC_PROXY 额外覆盖 Go 工具链（FrankenPHP），因为 Go 会忽略 ALL_PROXY</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SPC_PROXY</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;socks5h://127.0.0.1:1080&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> spc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;curl&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build-cli</span></span></code></pre></div><p><code>socks5h</code> 表示由代理端解析域名，通常这是你需要的模式。 StaticPHP 会把它作为 <code>ALL_PROXY</code> 传给 curl 和 git，并作为 <code>HTTP_PROXY</code>/<code>HTTPS_PROXY</code> 传给 Go （把 <code>socks5h://</code> 改写为 <code>socks5://</code>，这是 Go 唯一支持的 SOCKS 形式）。</p><p>如需长期生效，可将其写入 <code>config/env.ini</code> 或 <code>config/env.custom.ini</code>：</p><div class="language-ini"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[global]</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">SPC_PROXY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;socks5h://127.0.0.1:1080&quot;</span></span></code></pre></div><h2 id="doctor-无法修复某些问题" tabindex="-1">Doctor 无法修复某些问题 <a class="header-anchor" href="#doctor-无法修复某些问题" aria-label="Permalink to “Doctor 无法修复某些问题”">​</a></h2><p>在绝大部分情况下，doctor 模块都可以对缺失的系统环境进行自动修复和安装，但也存在特殊的环境无法正常使用自动修复功能。</p><p>由于系统限制（例如，Windows 下无法自动安装 Visual Studio 等软件），自动修复功能无法用于某些项目。 在遇到无法自动修复功能时，如果遇到 <code>Some check items can not be fixed</code> 字样，则表明无法自动修复。 请根据终端显示的方法提交 Issue 或自行修复环境。</p><h2 id="编译错误" tabindex="-1">编译错误 <a class="header-anchor" href="#编译错误" aria-label="Permalink to “编译错误”">​</a></h2><p>遇到编译错误时，如果没有开启 <code>-vvv</code> 日志，请先开启调试日志，然后确定报错的命令。 报错的终端输出对于修复编译错误非常重要。 在提交 Issue 时，请上传终端日志的最后报错片段（或整个终端日志输出），并且包含使用的 <code>spc</code> 命令和参数。</p><p>如果你是重复构建，请参考 <a href="./first-build.html#调试与重新构建">首次构建 - 调试与重新构建</a> 章节。</p>`,19)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};